      label: 'copy-button.scss',
      code: ':host {\n  display: inline-flex;\n}\n\n.copy {\n  align-items: center;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 999px;\n  color: var(--heading);\n  cursor: pointer;\n  display: inline-flex;\n  font: inherit;\n  font-size: 0.875rem;\n  gap: 0.375rem;\n  height: 2.5rem;\n  overflow: hidden;\n  padding-inline: 0.875rem 1rem;\n  transition:\n    background-color 0.2s var(--ease-out),\n    color 0.2s var(--ease-out),\n    border-color 0.2s var(--ease-out),\n    padding 0.3s var(--ease-out);\n\n  &:hover {\n    border-color: var(--muted);\n  }\n\n  &:active {\n    scale: 0.97;\n  }\n\n  &.is-copied {\n    background: var(--green-bg);\n    border-color: var(--green-text);\n    color: var(--green-text);\n    padding-inline: 1.25rem 1.5rem;\n  }\n}\n\n.icon {\n  display: grid;\n  height: 1.125rem;\n  width: 1.125rem;\n\n  svg {\n    fill: none;\n    grid-area: 1 / 1;\n    stroke: currentColor;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n    stroke-width: 2;\n    transition:\n      opacity 0.2s var(--ease-out),\n      scale 0.3s var(--ease-out);\n  }\n}\n\n.icon-check {\n  opacity: 0;\n  scale: 0.4;\n}\n\n.is-copied {\n  .icon-copy {\n    opacity: 0;\n    scale: 0.4;\n  }\n\n  .icon-check {\n    opacity: 1;\n    scale: 1;\n  }\n}\n\n.sr-only {\n  clip-path: inset(50%);\n  height: 1px;\n  overflow: hidden;\n  position: absolute;\n  white-space: nowrap;\n  width: 1px;\n}',
