      label: 'pin-button.scss',
      code: ':host {\n  display: inline-flex;\n}\n\n.pin {\n  align-items: center;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  color: var(--heading);\n  cursor: pointer;\n  display: inline-flex;\n  font: inherit;\n  font-size: 0.875rem;\n  gap: 0.5rem;\n  height: 2.75rem;\n  padding-inline: 0.875rem 1rem;\n  position: relative;\n  transition:\n    background-color 0.2s var(--ease-out),\n    border-color 0.2s var(--ease-out);\n\n  &:hover {\n    border-color: var(--muted);\n  }\n\n  &.is-pinned {\n    background: var(--yellow-bg);\n    border-color: var(--yellow-text);\n    color: var(--yellow-text);\n  }\n}\n\n.pin-icon {\n  fill: none;\n  height: 1.25rem;\n  rotate: 30deg;\n  stroke: currentColor;\n  stroke-linejoin: round;\n  stroke-width: 1.75;\n  transition: rotate 0.2s var(--ease-out);\n  width: 1.25rem;\n\n  .is-pinned & {\n    animation: pin-drop 0.6s linear;\n    fill: currentColor;\n    rotate: 0deg;\n  }\n}\n\n.pin-shadow {\n  background: currentColor;\n  border-radius: 50%;\n  bottom: 0.45rem;\n  height: 2px;\n  left: 1.05rem;\n  opacity: 0;\n  position: absolute;\n  width: 0.75rem;\n\n  .is-pinned & {\n    animation: pin-shadow 0.6s linear;\n    opacity: 0.25;\n  }\n}\n\n@keyframes pin-drop {\n  0% {\n    animation-timing-function: cubic-bezier(0.55, 0, 1, 0.45);\n    translate: 0 -0.75rem;\n  }\n  33% {\n    animation-timing-function: cubic-bezier(0, 0.55, 0.45, 1);\n    translate: 0 0;\n  }\n  50% {\n    animation-timing-function: cubic-bezier(0.55, 0, 1, 0.45);\n    translate: 0 -0.25rem;\n  }\n  66% {\n    animation-timing-function: cubic-bezier(0, 0.55, 0.45, 1);\n    translate: 0 0;\n  }\n  80% {\n    animation-timing-function: cubic-bezier(0.55, 0, 1, 0.45);\n    translate: 0 -0.08rem;\n  }\n  100% {\n    translate: 0 0;\n  }\n}\n\n@keyframes pin-shadow {\n  0% {\n    scale: 0.3 1;\n    opacity: 0;\n  }\n  33%,\n  66%,\n  100% {\n    scale: 1 1;\n    opacity: 0.25;\n  }\n}',
